/// <summary>
/// MPJ-21310 DEVOPS 34618
/// Responsible for dealing with item substitution logic.
/// </summary>
class METSalesItemSubstitution
{       
    // Referenced records
    METSalesLine                            metSalesLine;
    METSalesItemSubstitutionRounding        rounding;

    // Result
    boolean                                 newLineCreated;

}

Method.Source:
    /// <summary>
    /// Perform substitute checks/replacements.
    /// </summary>
    /// <param name = "_currentItemId">Current ItemId</param>
    /// <param name = "_inventDim">Inventory Dimensions</param>
    /// <param name = "_custAccount">Customer account</param>
    /// <param name = "_substitutionGroup">Substitution group</param>
    /// <param name = "_qtyOrdered">Invent quantity</param>
    /// <param name = "_outOfStockOnly">Out Of Stock Only</param>
    /// <param name = "_searchParent">Search parent item</param>
    /// <returns>True if the substitution item is found</returns>
    public boolean findSubstitutionItem(ItemId          _currentItemId, 
                                        InventDim       _inventDim,
                                        CustAccount     _custAccount,
                                        METSalesItemSubstitutionAccountRelation _substitutionGroup,
                                        InventQty       _qtyOrdered,  
                                        boolean         _outOfStockOnly = false,
                                        boolean         _searchParent = true)
    {
        METSalesItemSubstitutionParentChild matchingParentChild;
        METSalesItemSubstitute              matchingItemSub;
        date                                today = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

        boolean     continueSearch      = true;
        ItemId      currentSearchItemID = _currentItemId;
        container   itemsSearched;
        int         searchDepth         = 1;
        int         maxSearchDepth      = CustParameters::find().METSalesSubstituteMaxLevels;   
        boolean     found;        

        maxSearchDepth      = maxSearchDepth > 0 ? min(maxSearchDepth, METConstants::MaxSubstituteLevels) : METConstants::MaxSubstituteLevels;       

        while(continueSearch && 
              searchDepth <= maxSearchDepth &&
              !conFind(itemsSearched, currentSearchItemID))
        {
            itemsSearched += currentSearchItemID;

            METSalesItemSubstitutionParentChild parentChild;

            if (_searchParent)
            {
                parentChild = this.searchParentChild(currentSearchItemID, _inventDim.InventSiteId);
            }
            
            if (parentChild)
            {
                currentSearchItemID = parentChild.ParentItemID;
                matchingParentChild = parentChild;
                matchingItemSub     = null;                
            }
            else
            {
                METSalesItemSubstitute itemSub;
                
                select firstonly validtimestate(today) itemSub
                    order by AccountCode asc
                    where   itemSub.ItemId              == currentSearchItemID
                    &&     (itemSub.InventSiteId == _inventDim.InventSiteId || itemSub.InventSiteId == METConstants::emptyString)
                    && ((!_outOfStockOnly && itemSub.SubstitutionCode != METSalesItemSubstitutionCode::OutOfStock) 
                        || (_outOfStockOnly && itemSub.SubstitutionCode == METSalesItemSubstitutionCode::OutOfStock))                    
                    &&  (   // table/group/all match
                        (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::Table &&
                            itemSub.AccountRelation == _custAccount)
                    ||  (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::GroupId &&
                            itemSub.AccountRelation == _substitutionGroup)
                    ||  (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::All &&
                            itemSub.AccountRelation == METConstants::emptyString)
                    );
                
                if(itemSub)
                {
                    matchingParentChild     = null;
                
                    switch(itemSub.SubstitutionCode)
                    {
                        case METSalesItemSubstitutionCode::Always:
                            currentSearchItemID     = itemSub.SubstituteItemID;
                            matchingItemSub         = itemSub;
                            break;

                        case METSalesItemSubstitutionCode::Replacement:
                            if(MetItemSiteSettingsSetup::find(currentSearchItemID, _inventDim.InventSiteId).ItemStatus == METConstants::Deleted)
                            {
                                currentSearchItemID     = itemSub.SubstituteItemID;
                                matchingItemSub         = itemSub;
                            }
                            else
                            {
                                continueSearch  = false;
                            }
                            break;

                        case METSalesItemSubstitutionCode::NoAlternative:
                        case METSalesItemSubstitutionCode::Never:
                            continueSearch  = false;
                            break;

                        case METSalesItemSubstitutionCode::OutOfStock:
                            if (this.queryOnHandQty(currentSearchItemID, _inventDim) < _qtyOrdered)
                            {
                                if (this.queryOnHandQty(itemSub.SubstituteItemID, _inventDim) >= _qtyOrdered)
                                {
                                    matchingItemSub     = itemSub;
                                    continueSearch      = false;
                                }
                                else
                                {
                                    if (!itemSub.OrderOriginalItem)
                                    {
                                        matchingItemSub     = itemSub;
                                    }

                                    currentSearchItemID     = itemSub.SubstituteItemID;
                                }
                            }
                            else
                            {
                                continueSearch      = false;
                            }
                            
                            break;

                        default:
                            break;
                    }                        
                }                
                else
                {
                    continueSearch = false;
                }
            }

            searchDepth++;
        }        
        
        if(matchingItemSub)
        {
            if(!metSalesLine.SubstituteOriginalItemID)
            {
                metSalesLine.SubstituteOriginalItemID       = _currentItemId;
            }

            metSalesLine.SubstituteReplacementItemID        = matchingItemSub.SubstituteItemId;
            metSalesLine.SubstituteParentItemID             = METConstants::emptyString;
            metSalesLine.SubstitutionType                   = METSalesItemSubstitutionType::SubstitutionCode;
            metSalesLine.SubstitutionCode                   = matchingItemSub.SubstitutionCode;
            metSalesLine.SubstitutionSetupRefRecID          = matchingItemSub.RecId;
            rounding                                        = matchingItemSub.Rounding;

            found   = true;            
        }

        else if(matchingParentChild)
        {
            if(!metSalesLine.SubstituteOriginalItemID)
            {
                metSalesLine.SubstituteOriginalItemID       = _currentItemId;
            }
            metSalesLine.SubstituteReplacementItemID        = matchingParentChild.ParentItemID;
            metSalesLine.SubstituteParentItemID             = matchingParentChild.ParentItemID;
            metSalesLine.SubstitutionType                   = METSalesItemSubstitutionType::ParentChild;
            metSalesLine.SubstitutionCode                   = METSalesItemSubstitutionCode::None;
            metSalesLine.SubstitutionSetupRefRecID          = matchingParentChild.RecId;
            rounding                                        = matchingParentChild.Rounding;

            found   = true;            
        }
      
        if (found)
        {
            metSalesLine.Indicators     = metSalesLine.Indicators ?
                                          (METConstants::S + METConstants::Comma + metSalesLine.Indicators) :
                                          METConstants::S;
        }
        
        return found;
    }

    /// <summary>
    /// Search for parent/child relationship.
    /// </summary>
    /// <param name = "_itemID">_itemID</param>
    /// <param name = "_inventSiteId">_inventSiteId</param>
    /// <returns>Matching record or null</returns>
    protected METSalesItemSubstitutionParentChild searchParentChild(ItemId _itemID, InventSiteId    _inventSiteId)
    {
        METSalesItemSubstitutionParentChild parentChild; 
       
        select firstonly parentChild
            where   (parentChild.InventSiteId == METConstants::emptyString || parentChild.InventSiteId == _inventSiteId)
            &&      parentChild.ChildItemID     == _itemID;

        if(parentChild)
        {
            return parentChild;
        }
        
        return null;
    }

    /// <summary>
    /// Copy sales line to new line with specified item id.
    /// </summary>
    /// <param name = "_salesLine">Sales line</param>
    /// <param name = "_metSalesLine">MET Sales line</param>
    /// <returns>New sales order line</returns>
    public SalesLine copyToNewLine(SalesLine        _salesLine, 
                                   METSalesLine     _metSalesLine)
    {
        SalesLine       salesLineNew;
        SalesLine       existingLine    = _salesLine;
        InventSiteId    inventSiteId    = existingLine.inventDim().InventSiteId;
        SalesTable      salesTable      = existingLine.salesTable();
        METSalesLine    metSalesLineNew;
        boolean         cancelSalesLine;

        ttsbegin;

        buf2Buf(_metSalesLine, metSalesLineNew);
        metSalesLineNew.salesLine   = 0;

        salesLineNew.initFromSalesTable(salesTable);
        salesLineNew.initFromSalesLine(existingLine, true, true, true);
        salesLineNew.ItemId             = metSalesLineNew.SubstituteReplacementItemID;
        salesLineNew.PackedExtensions   = conNull();
        
        salesLineNew.itemIdChanged();

        salesLineNew.SalesUnit  = this.substitutionItemSalesUnit(salesLineNew.ItemId, inventSiteId);

        salesLineNew.SalesQty   = this.substitutionItemSalesQty(existingLine.ItemId,
                                                                salesLineNew.ItemId,
                                                                inventSiteId,
                                                                salesLineNew.SalesUnit,
                                                                existingLine.QtyOrdered,
                                                                this.parmRounding());

        salesLineNew.METSkipQuantityUpdatePrompts = true;
        SalesLine::modifySalesQty(salesLineNew,
                                  salesLineNew.inventDim(),
                                  false,
                                  false);
        salesLineNew.METSkipQuantityUpdatePrompts = false;

        if(!METSalesOrderGuideExecution::isItemOrderable(salesTable.CustAccount, salesLineNew.ItemId))
        {
            metSalesLineNew.ReasonId    = METCustParameters::Find().OrderGuideNotInRangeReasonId;
            cancelSalesLine     = true;
        }
        else
        {
            if (this.applyPalletRounding(salesLineNew, metSalesLineNew))
            {
                salesLineNew.METSkipQuantityUpdatePrompts = true;
                SalesLine::modifySalesQty(salesLineNew,
                                          salesLineNew.inventDim(),
                                          false,
                                          false);
                salesLineNew.METSkipQuantityUpdatePrompts = false;
            }
        }

        salesLineNew.metPackMETSalesLine(metSalesLineNew);
        
        salesLineNew.createLine(true, false, false, false, false);        

        metSalesLine    = metSalesLineNew;

        existingLine.selectForUpdate(true);
        existingLine.delete();

        if(cancelSalesLine)
        {
            salesLineNew.selectForUpdate(true);
            SalesUpdateRemain::construct().updateDeliverRemainder(salesLineNew, 0, 0);            
        }
        ttscommit;

        return salesLineNew;
    }

 /// <summary>
 /// Return true if new line created.
 /// </summary>
 /// <returns>Result</returns>
public boolean getNewLineCreated()
{
    return newLineCreated;
}

/// <summary>
/// Rounding
/// </summary>
/// <param name = "_rounding">_rounding</param>
/// <returns>METSalesItemSubstitutionRounding</returns>
public METSalesItemSubstitutionRounding parmRounding(METSalesItemSubstitutionRounding _rounding = rounding)
{
    rounding    = _rounding;
    return rounding;
}

/// <summary>
/// parmMetSalesLine
/// </summary>
/// <param name = "_metSalesLine">_metSalesLine</param>
/// <returns>METSalesLine</returns>
public METSalesLine parmMetSalesLine(METSalesLine _metSalesLine = metSalesLine)
{
    metSalesLine = _metSalesLine;
    return metSalesLine;
}

    /// <summary>
    /// Find on-hand quantity for specified item
    /// </summary>
    /// <param name = "_itemID">_itemID</param>
    /// <param name = "_inventDim">_inventDim</param>
    /// <returns>On-hand quantity</returns>
    public Qty queryOnHandQty(ItemId _itemID, InventDim _inventDim)
    {
        InventDimParm   onHandDimParm;
        onHandDimParm.initFromInventDim(_inventDim);
        InventOnhand    onHand = InventOnhand::newItemDim(_itemId, _inventDim, onHandDimParm);
        Qty             onHandQty;
        

        if(CustParameters::find().METSubstitutionIncludeOnOrderInventory)
        {
            onHandQty = onHand.availOrdered(true);            
        }
        else
        {
            onHandQty = onHand.availPhysical();            
        }
        return onHandQty;
    }

    /// <summary>
    /// MPJ-21310
    /// Substitution item sales unit.
    /// </summary>
    /// <param name = "_replacementItemId">Replacement item</param>
    /// <param name = "_inventSiteId">Invent site Id</param>
    /// <returns>Substitution item sales unit</returns>
    public UnitOfMeasureSymbol substitutionItemSalesUnit(ItemId          _replacementItemId,
                                                         InventSiteId    _inventSiteId)
    {
        UnitOfMeasureSymbol replacementSalesUnit;
        InventDim           siteDim;

        siteDim.InventSiteID    = _inventSiteId;
        siteDim                 = InventDim::findDim(siteDim);

        InventItemSalesSetup salesSetup = InventItemSalesSetup::find(
            _replacementItemId,
            siteDim.inventDimId);

        if(!salesSetup)
        {
            salesSetup = InventItemSalesSetup::findDefault(_replacementItemId);
        }

        replacementSalesUnit    = (salesSetup && salesSetup.METSalesUnit) ?
                                  salesSetup.METSalesUnit :
                                  InventTableModule::find(_replacementItemId, ModuleInventPurchSales::Sales).UnitId;        
        
        return replacementSalesUnit;
    }

    /// <summary>
    /// MPJ-21310
    /// Check and update quantity/unit if required.
    /// </summary>
    /// <param name = "_originalItemId">Original item id on sales line</param>
    /// <param name = "_replacementItemId">Replacement item</param>
    /// <param name = "_inventSiteId">Invent site Id</param>
    /// <param name = "_replacementItemSalesUnit">Replacement item sales unit</param>
    /// <param name = "_qtyOrdered">Invent quantity ordered</param>
    /// <param name = "_rounding">Rounding</param>
    /// <returns>Validation result</returns>
    public SalesQty substitutionItemSalesQty(   ItemId                              _originalItemId,
                                                ItemId                              _replacementItemId,
                                                InventSiteId                        _inventSiteId,
                                                UnitOfMeasureSymbol                 _replacementItemSalesUnit,
                                                InventQty                           _qtyOrdered,
                                                METSalesItemSubstitutionRounding    _rounding)
    {
        InventTable         originalItem            = InventTable::find(_originalItemId);
        InventTableModule   originalItemInvent      = originalItem.inventTableModuleInvent();
        InventTable         replacementItem         = InventTable::find(_replacementItemId);
        InventTableModule   replacementItemInvent   = replacementItem.inventTableModuleInvent();
        Qty                 replacementQtySalesUnit;
        InventDim           siteDim;

        siteDim.InventSiteID    = _inventSiteId;
        siteDim                 = InventDim::findDim(siteDim);
        
        
        if(originalItemInvent.UnitId == replacementItemInvent.UnitID)
        {
            replacementQtySalesUnit = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                replacementItem.ItemId,
                siteDim.inventDimId,
                _qtyOrdered,
                replacementItemInvent.UnitId,
                _replacementItemSalesUnit,
                true,
                false);

            if(real2int(replacementQtySalesUnit) != replacementQtySalesUnit)
            {
                Qty     roundedSalesQty;
                boolean roundingApplied;
                int     roundingPrecision = 1;

                switch(_rounding)
                {
                    case METSalesItemSubstitutionRounding::ToNearest:
                        roundedSalesQty = round(replacementQtySalesUnit, roundingPrecision);
                        roundingApplied = true;
                        break;
                    case METSalesItemSubstitutionRounding::Up:
                        roundedSalesQty = roundUp(replacementQtySalesUnit, roundingPrecision);
                        roundingApplied = true;
                        break;
                    case METSalesItemSubstitutionRounding::Down:
                        roundedSalesQty = roundDown(replacementQtySalesUnit, roundingPrecision);
                        roundingApplied = true;
                        break;
                }

                if(roundingApplied)
                {
                    replacementQtySalesUnit = roundedSalesQty;
                }
                else
                {
                    if(replacementQtySalesUnit < 1)
                    {
                        replacementQtySalesUnit = 1;
                    }
                }
            }
        }
            
        return replacementQtySalesUnit;
    }

/// <summary>
/// construct
/// </summary>
/// <returns>New instance</returns>
static public METSalesItemSubstitution construct()
{
    return new METSalesItemSubstitution();
}

/// <summary>
/// Max. search depth. This is configurable in the inventory parameters but may
/// not exceed this number.
/// </summary>
/// <returns>Result</returns>
static public int maxSearchDepth()
{
    return METConstants::MaxSubstituteLevels;
}

    /// <summary>
    /// Performs pallet rounding.
    /// </summary>
    /// <param name = "_salesline">SalesLine</param>
    /// <param name = "_metSalesLine">METSalesLine</param>
    /// <returns>True if the pallet rounding is successful</returns>
    public boolean  applyPalletRounding(SalesLine      _salesline, METSalesLine     _metSalesLine)
    {
        SalesQty            originalSalesQty    = _salesline.SalesQty;
        SalesTable          salesTable  = SalesTable::find(_salesline.SalesId);
        InventQty           newOrderedQty;
        InventDim           inventDim   = _salesline.inventDim();
        boolean             modified;

        METPalletRounding   metPalletRounding;

        if (salesTable.agreementIsLinked())
        {
            return false;
        }

        metPalletRounding   = new METPalletRounding();

        newOrderedQty   = metPalletRounding.applyPalletRounding(_salesline.ItemId,
                                                                salesTable.CustAccount,
                                                                inventDim.InventSiteId,
                                                                _salesline.QtyOrdered);

        if ((newOrderedQty > _salesline.QtyOrdered) &&
            METCustParameters::Find().PalletRoundingCheckStock)
        {
            if (newOrderedQty > this.queryOnHandQty(_salesline.ItemId, inventDim))
            {
                newOrderedQty   = _salesline.QtyOrdered;
            }
        }

        if (newOrderedQty > _salesline.QtyOrdered)
        {
            UnitOfMeasureSymbol     inventUnit  = _salesline.inventTable().inventUnitId();

            if (inventUnit == _salesline.SalesUnit)
            {
                _salesline.salesQty = newOrderedQty;
            }
            else
            {
                SalesQty    newSalesQty = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_salesline.ItemId,
                                                                                                  inventDim.inventDimId,
                                                                                                  newOrderedQty,
                                                                                                  inventUnit,
                                                                                                  _salesline.SalesUnit,
                                                                                                  NoYes::Yes);
                newSalesQty  = decRound(newSalesQty, InventTable::inventDecimals(_salesline.ItemId));

                _salesline.salesQty = newSalesQty;
            }

            _metSalesLine.PalletRoundingApplied       = NoYes::Yes;
            _metSalesLine.PalletRoundingOriginalQty   = originalSalesQty;            

            modified = true;
        }

        return modified;
    }
